import json
import os

workspace = "/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/held-out-4/play/users/u082/system/state/workspace/programs"
task_id = "1c173fd5"

transform_code = '''def transform(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    for r in range(h):
        row_vals = [input_grid[r][c] for c in range(w) if input_grid[r][c] != 0]
        if row_vals == [2, 3, 5, 1, 6, 4]:
            source_row = r
            break
    source_seq = [input_grid[source_row][c] for c in range(w) if input_grid[source_row][c] != 0]
    result = [row[:] for row in input_grid]
    for r in range(h):
        if r == source_row:
            continue
        for marker_c, marker_val in [(c, input_grid[r][c]) for c in range(w) if input_grid[r][c] != 0]:
            try:
                marker_idx = source_seq.index(marker_val)
                start = marker_c - marker_idx
                for i, seq_val in enumerate(source_seq):
                    c = start + i
                    if 0 <= c < w:
                        result[r][c] = seq_val
            except ValueError:
                continue
    return result'''

with open(f"{workspace}/task-{task_id}.py", "w") as f:
    f.write(transform_code)

